package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;

public class AgentBRT_Lang_6_raw_diff_Test {

    private static class HexTranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            int codepoint = Character.codePointAt(input, index);
            out.write(Integer.toHexString(codepoint));
            return Character.charCount(codepoint);
        }
    }

    @Test
    public void testReproduceBug() {
        CharSequenceTranslator translator = new HexTranslator();
        String input = "A\uD835\uDD0A"; // 'A' followed by a surrogate pair representing a mathematical italic capital A
        StringWriter writer = new StringWriter();
        try {
            translator.translate(input, writer);
        } catch (IOException e) {
            fail("IOException should not occur");
        }
        String expectedOutput = "41" + Integer.toHexString(Character.codePointAt(input, 1));
        assertEquals("Translation did not produce expected output", expectedOutput, writer.toString());
    }
}

